using Microsoft.Extensions.ML;
using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train model at startup
using var tempLoggerFactory = LoggerFactory.Create(lb => lb.AddConsole());
var (modelPath, labelNames) = TrainModel(builder.Environment.ContentRootPath, tempLoggerFactory);

builder.Services.AddSingleton(labelNames);
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

static (string ModelPath, string[] Labels) TrainModel(string contentRoot, ILoggerFactory loggerFactory)
{
    var logger = loggerFactory.CreateLogger("ModelTraining");
    var dataPath = Path.Combine(contentRoot, "Data", "tickets.csv");
    var modelPath = Path.Combine(contentRoot, "Data", "model.zip");

    var mlContext = new MLContext(seed: 42);

    IDataView data = mlContext.Data.LoadFromTextFile<TicketInput>(
        dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

    var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

    var pipeline = mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject))
        .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
        .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
        .Append(mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category)))
        .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
        .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

    logger.LogInformation("Training model...");
    var model = pipeline.Fit(split.TrainSet);

    // Extract label names in score order from the trained model
    var schema = model.Transform(split.TrainSet).Schema;
    var labelColumn = schema["Score"];
    var slotNames = new VBuffer<ReadOnlyMemory<char>>();
    labelColumn.GetSlotNames(ref slotNames);
    var labels = slotNames.DenseValues().Select(v => v.ToString()).ToArray();

    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.MulticlassClassification.Evaluate(predictions, "Label");

    logger.LogInformation("===== Model Evaluation Metrics =====");
    logger.LogInformation("MacroAccuracy:    {MacroAccuracy:F4}", metrics.MacroAccuracy);
    logger.LogInformation("MicroAccuracy:    {MicroAccuracy:F4}", metrics.MicroAccuracy);
    logger.LogInformation("LogLoss:          {LogLoss:F4}", metrics.LogLoss);
    logger.LogInformation("LogLossReduction: {LogLossReduction:F4}", metrics.LogLossReduction);

    mlContext.Model.Save(model, data.Schema, modelPath);
    logger.LogInformation("Model saved to {Path}", modelPath);

    return (modelPath, labels);
}

